"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";

function SparkleIcon() {
  return (
    <svg viewBox="0 0 24 24" width="12" height="12" fill="currentColor" aria-hidden>
      <path d="M12 2.5c.4 3.6 1.4 5.9 3 7.5s3.9 2.6 7.5 3c-3.6.4-5.9 1.4-7.5 3s-2.6 3.9-3 7.5c-.4-3.6-1.4-5.9-3-7.5S5.1 13.4 1.5 13c3.6-.4 5.9-1.4 7.5-3s2.6-3.9 3-7.5z" />
    </svg>
  );
}

function ShuffleIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="m18 4 3 3-3 3" />
      <path d="M3 7h6c1.5 0 2.5.5 3.5 2l5 8c1 1.5 2 2 3.5 2h0" />
      <path d="m18 20 3-3-3-3" />
      <path d="M3 17h6c1.5 0 2.5-.5 3.5-2l1-1.6" />
      <path d="m10.5 8.5.4-.7c1-1.5 2-2 3.5-2H21" />
    </svg>
  );
}

function ArrowIcon() {
  return (
    <svg viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M5 12h14" />
      <path d="m13 6 6 6-6 6" />
    </svg>
  );
}

function SendIcon() {
  return (
    <svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="m3 3 18 9-18 9 4-9-4-9Z" />
    </svg>
  );
}

function UndoIcon() {
  return (
    <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      <path d="M3 12a9 9 0 1 0 2.6-6.3" />
      <path d="M3 4v5h5" />
    </svg>
  );
}

export function Suggestion({
  suggestionSets,
  onSelect,
}: {
  /** One or more batches of suggestion strings; the shuffle icon cycles between batches. */
  suggestionSets: string[][];
  onSelect?: (text: string) => void;
}) {
  const [setIndex, setSetIndex] = useState(0);
  const [selected, setSelected] = useState<string | null>(null);
  const shouldReduceMotion = useReducedMotion();
  const suggestions = suggestionSets[setIndex] ?? [];

  const handleSelect = (text: string) => {
    setSelected(text);
    onSelect?.(text);
  };

  return (
    <div className="w-full max-w-md">
      <div className="mb-2.5 flex items-center justify-between">
        <p className="text-xs font-semibold uppercase tracking-wide text-slate-400 dark:text-slate-500">Suggested replies</p>
        {!selected && suggestionSets.length > 1 && (
          <button
            type="button"
            onClick={() => setSetIndex((i) => (i + 1) % suggestionSets.length)}
            aria-label="Show different suggestions"
            title="Show different suggestions"
            className="inline-flex h-7 w-7 items-center justify-center rounded-full text-slate-400 transition-colors hover:bg-black/5 hover:text-slate-600 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:hover:bg-white/10 dark:hover:text-slate-300"
          >
            <ShuffleIcon />
          </button>
        )}
      </div>

      <AnimatePresence mode="wait" initial={false}>
        {selected ? (
          <motion.div
            key="composer"
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: -6, scale: 0.98 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            transition={{ duration: 0.28, ease: [0.16, 1, 0.3, 1] }}
            className="flex items-center gap-2.5 rounded-2xl border border-emerald-500/30 bg-emerald-500/5 px-4 py-3 dark:border-emerald-400/25 dark:bg-emerald-400/5"
          >
            <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-emerald-600 text-white">
              <SendIcon />
            </span>
            <p className="flex-1 truncate text-sm font-medium text-slate-800 dark:text-slate-100">{selected}</p>
            <button
              type="button"
              onClick={() => setSelected(null)}
              className="inline-flex shrink-0 items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium text-slate-500 transition-colors hover:bg-black/5 hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-white/10 dark:hover:text-slate-200"
            >
              <UndoIcon />
              Start over
            </button>
          </motion.div>
        ) : (
          <motion.div
            key={`row-${setIndex}`}
            initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={shouldReduceMotion ? { opacity: 0 } : { opacity: 0 }}
            transition={{ duration: 0.15 }}
            className="relative"
          >
            <div
              className="flex gap-2 overflow-x-auto pb-1 pl-0.5 pr-6 pt-0.5 scrollbar-hide"
              style={{
                WebkitMaskImage: "linear-gradient(to right, black 0, black calc(100% - 28px), transparent 100%)",
                maskImage: "linear-gradient(to right, black 0, black calc(100% - 28px), transparent 100%)",
              }}
            >
              {suggestions.map((s, i) => (
                <motion.button
                  key={s}
                  type="button"
                  onClick={() => handleSelect(s)}
                  initial={shouldReduceMotion ? { opacity: 0 } : { opacity: 0, y: 8, scale: 0.94 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  transition={{ duration: 0.3, delay: i * 0.06, ease: [0.16, 1, 0.3, 1] }}
                  whileHover={shouldReduceMotion ? undefined : { y: -2 }}
                  whileTap={{ scale: 0.96 }}
                  className="group inline-flex shrink-0 items-center gap-1.5 whitespace-nowrap rounded-full border border-slate-200/70 bg-white px-3.5 py-2 text-sm font-medium text-slate-700 shadow-sm transition-colors hover:border-emerald-500/40 hover:bg-emerald-500/5 hover:text-emerald-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:border-white/10 dark:bg-neutral-950 dark:text-slate-300 dark:hover:border-emerald-400/30 dark:hover:bg-emerald-400/5 dark:hover:text-emerald-400"
                >
                  <span className="text-emerald-500 dark:text-emerald-400">
                    <SparkleIcon />
                  </span>
                  {s}
                  <span className="text-slate-300 opacity-0 transition-opacity group-hover:opacity-100 dark:text-slate-600">
                    <ArrowIcon />
                  </span>
                </motion.button>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
